import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BIas3y6W.js";const g=JSON.parse('{"title":"Week 1 — Hello, Vibe Coding","description":"","frontmatter":{"source":"weeks/01-hello-vibe-coding/README.md"},"headers":[],"relativePath":"weeks/01-hello-vibe-coding/index.md","filePath":"weeks/01-hello-vibe-coding/index.md"}'),n={name:"weeks/01-hello-vibe-coding/index.md"};function i(s,e,h,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="week-1--hello-vibe-coding" tabindex="-1">Week 1 — Hello, Vibe Coding <a class="header-anchor" href="#week-1--hello-vibe-coding" aria-label="Permalink to &quot;Week 1 — Hello, Vibe Coding&quot;">​</a></h1><blockquote><p>You can build a working web page just by describing it to an AI, but you only own it once you can explain what is inside and change it yourself.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (30 min, plus week 0)</td><td>Finish the <a href="./../../setup/">week 0 pre-work</a> before the first class (60–90 min). Read this page and skim <a href="./../../setup/python-to-javascript.html">From Python to JavaScript</a>. Bring a laptop and charger</td></tr><tr><td><strong>Studio A</strong></td><td>Concept talk: vibe coding, how an LLM writes code, privacy and the safety contract. Then build your personal page in a chat assistant&#39;s live preview</td></tr><tr><td><strong>Studio B</strong></td><td>Ask the AI to explain your page section by section, then change its HTML, CSS and JavaScript by hand (🔴 AI off). Exit ticket</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before)</td><td><code>index.html</code>, with one feature you wrote by hand, uploaded to Canvas (the course&#39;s learning management system, not Gemini&#39;s Canvas tool) · on Canvas: safety contract, self-assessment, reflection · GitHub Education application sent · half of the AI Fluency course. Full list: <a href="./homework.html#deliverables-checklist">deliverables checklist</a></td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: building, customizing and explaining your page · 🟡 AI limited: none this week · 🔴 AI off: the hand changes, the feature you write by hand, the exit ticket, the self-assessment and the reflection</td></tr><tr><td><strong>Must read</strong></td><td>This page, the <a href="./lab.html">lab</a>, the <a href="./homework.html">homework</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./prompt-starters.html">Prompt starters</a> · <a href="./../../resources/web-basics.html">How the Web Works</a> · <a href="./../../resources/troubleshooting.html">Troubleshooting</a> · <a href="./../../resources/glossary.html">Glossary</a> · <a href="./../../TOOLS.html">Tool Handout</a> · <a href="./../../resources/accessibility.html">Screen reader and keyboard guide</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>A saved <code>index.html</code> that opens in your browser and contains at least one change you made by hand. Week 2 publishes it</td></tr><tr><td><strong>Time</strong></td><td>Studios 2½ h · outside about 6 h (prep up to 30 min, homework core about 5 h including project time and the reflection); stretch is optional</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Explain what &quot;vibe coding&quot; originally meant, and how it differs from <em>agentic engineering</em>.</li><li>Describe how a large language model (LLM) produces code, and why that means you must check it.</li><li>Name the three languages of a web page (HTML, CSS, JavaScript), say what each does, and find each in a one-file page.</li><li>Build a one-file page with the loop <strong>describe → generate → run → customize</strong>, writing prompts in four parts: <strong>Goal · Context · Constraints · Done when</strong>.</li><li>Ask an AI to explain code, and check the explanation against the code and the page.</li><li>Change a page&#39;s HTML, CSS and JavaScript <strong>by hand</strong>, with no AI, predicting the result first.</li><li>Set your AI tools&#39; privacy settings and say what you must never paste into one.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ Finish the part of the <a href="./../../setup/">week 0 pre-work</a> that comes before the first class: a <strong>GitHub account</strong>, a <strong>personal Google account</strong> (school or work accounts often block Gemini), and the <a href="./../../setup/privacy-settings.html">privacy settings</a> on every AI tool you plan to use.</li><li>☐ Skim <a href="./../../setup/python-to-javascript.html">From Python to JavaScript</a> (about 15 minutes). Your page&#39;s behavior is written in JavaScript; this page maps it onto the Python you know. You&#39;ll have it open in Studio B.</li><li>☐ Bring a laptop and charger, and check you can sign in to Google and GitHub on it.</li><li>☐ Think of three things about yourself you&#39;re happy to make <strong>public</strong>: a first name or nickname, some interests, something you&#39;re learning.</li></ul><p>The rest of week 0 (signing the <a href="./../../setup/safety-contract.html">safety contract</a>, the self-assessment, GitHub Education) is part of this week&#39;s homework.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Under 18, or in the EEA, UK or Switzerland? Some tools have age or region rules. Your instructor will tell you which to use.</p></div><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Welcome · concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-01.html" target="_blank" rel="noreferrer">slides</a>) · live demo · lab: privacy check, build &quot;Hello, Web&quot;, save your work · checkpoint share</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell, with introductions · mini-lesson: reading a page as a programmer · lab: a guided tour of your code, then changes by hand (🔴 AI off) · project time · exit ticket (🔴 AI off)</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="./lab.html">Lab</a></td><td>Step-by-step, both studios (must read)</td></tr><tr><td><a href="./homework.html">Homework</a></td><td>Core and stretch, with the deliverables checklist (must read)</td></tr><tr><td><a href="./prompt-starters.html">Prompt starters</a></td><td>Starting, customizing, understanding and fixing prompts</td></tr><tr><td><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-01.html" target="_blank" rel="noreferrer">Slides</a></td><td>The 15-minute concept talk</td></tr></tbody></table><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>If you are working through this week on your own, read this section, then do the <a href="./lab.html">lab</a>. The <a href="./../../resources/self-paced.html">self-paced path</a> says what to do instead of the pair and class activities.</p><h3 id="vibe-coding-then-and-now" tabindex="-1">Vibe coding, then and now <a class="header-anchor" href="#vibe-coding-then-and-now" aria-label="Permalink to &quot;Vibe coding, then and now&quot;">​</a></h3><p>In February 2025 Andrej Karpathy described <a href="./../../resources/glossary.html#vibe-coding">vibe coding</a>: accept everything the AI writes without reading it, and paste any error back in. Fine, he said, for throwaway projects (<a href="https://arxiv.org/pdf/2507.22614" target="_blank" rel="noreferrer">his post, reproduced in Geng et al.</a>). Simon Willison&#39;s golden rule drew the line: never commit code you couldn&#39;t explain to someone else (<a href="https://simonwillison.net/2025/Mar/19/vibe-coding/" target="_blank" rel="noreferrer">Willison, 2025</a>). By 2026 Karpathy contrasted it with <a href="./../../resources/glossary.html#agentic-engineering"><em>agentic engineering</em></a>: building serious software with AI agents while staying responsible for understanding and securing it (<a href="https://karpathy.bearblog.dev/sequoia-ascent-2026/" target="_blank" rel="noreferrer">Karpathy, 2026</a>). This course starts at the vibe-coding end and adds one engineering habit a week.</p><h3 id="how-an-llm-writes-code" tabindex="-1">How an LLM writes code <a class="header-anchor" href="#how-an-llm-writes-code" aria-label="Permalink to &quot;How an LLM writes code&quot;">​</a></h3><p>A <a href="./../../resources/glossary.html#llm">large language model</a> predicts what text comes next, one <a href="./../../resources/glossary.html#token">token</a> (a word or piece of a word) at a time. Code is text, so it predicts code the same way. Four consequences matter every day:</p><ul><li><strong>It only sees its <a href="./../../resources/glossary.html#context-window">context window</a></strong>: this chat and anything you paste in. Not your screen, not your files.</li><li><strong>The same prompt can give different answers.</strong></li><li><strong>It can be confidently wrong.</strong> It produces plausible text, not checked facts (<a href="./../../resources/glossary.html#hallucination">hallucination</a>).</li><li><strong>It has a <a href="./../../resources/glossary.html#knowledge-cutoff">knowledge cutoff</a></strong>, so it may not know recent tools or changes.</li></ul><p>So you check its work by running it and reading it. Being able to program doesn&#39;t make checking optional: in a 2025 trial, experienced developers using AI were 19% slower while believing they were faster (<a href="https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/" target="_blank" rel="noreferrer">METR, 2025</a>).</p><h3 id="what-a-web-page-is" tabindex="-1">What a web page is <a class="header-anchor" href="#what-a-web-page-is" aria-label="Permalink to &quot;What a web page is&quot;">​</a></h3><p>A web page is a text file your <a href="./../../resources/glossary.html#browser">browser</a> reads and runs:</p><table tabindex="0"><thead><tr><th>Language</th><th>Job</th><th>Example</th></tr></thead><tbody><tr><td><a href="./../../resources/glossary.html#html"><strong>HTML</strong></a></td><td>Structure: what is on the page</td><td><code>&lt;h1&gt;Hi, I&#39;m Sam&lt;/h1&gt;</code></td></tr><tr><td><a href="./../../resources/glossary.html#css"><strong>CSS</strong></a></td><td>Style: how it looks</td><td><code>h1 { color: teal; }</code></td></tr><tr><td><a href="./../../resources/glossary.html#javascript"><strong>JavaScript</strong></a></td><td>Behavior: what happens when you click or type</td><td><code>button.addEventListener(&quot;click&quot;, wave);</code></td></tr></tbody></table><p>Where a Python script runs top to bottom and ends, a page&#39;s JavaScript mostly waits for <strong>events</strong> (a click, a key press) and runs a function when one happens, changing the page through the <a href="./../../resources/glossary.html#dom">DOM</a>, the browser&#39;s live model of the HTML. This week all three live in one file, <code>index.html</code>.</p><h3 id="the-loop-then-the-hand-changes" tabindex="-1">The loop, then the hand changes <a class="header-anchor" href="#the-loop-then-the-hand-changes" aria-label="Permalink to &quot;The loop, then the hand changes&quot;">​</a></h3><p><strong>Describe → generate → run → customize:</strong> describe what you want in four parts, let the AI generate it, run it in the <a href="./../../resources/glossary.html#live-preview">live preview</a>, then ask for one change at a time. From week 3 this grows into the full <a href="./../../resources/safe-loop.html">Safe Loop</a>.</p><p>An AI can write the page, but it can&#39;t understand it <em>for</em> you. So in Studio B you ask it to explain each part, check the explanation, and change the code yourself with the AI off: your first practice of the <a href="./../../resources/without-ai-skills.html">six skills you must show without AI</a>.</p><h3 id="ai-on-ai-limited-ai-off" tabindex="-1">AI on, AI limited, AI off <a class="header-anchor" href="#ai-on-ai-limited-ai-off" aria-label="Permalink to &quot;AI on, AI limited, AI off&quot;">​</a></h3><p>Every task carries a label. <strong>🟢 AI on:</strong> use AI freely. <strong>🟡 AI limited:</strong> the AI may comment or hint, but the work is yours. <strong>🔴 AI off:</strong> close the AI tabs and work alone. Full policy: <a href="./../../assessment/#ai-use-policy">assessment guide</a>.</p><h3 id="privacy-and-the-safety-contract" tabindex="-1">Privacy and the safety contract <a class="header-anchor" href="#privacy-and-the-safety-contract" aria-label="Permalink to &quot;Privacy and the safety contract&quot;">​</a></h3><p>Free AI tools may store your chats, train on them and let people review them. Turn training off where you can, and never paste passwords, keys or other people&#39;s personal information: the first two rules of the <a href="./../../setup/safety-contract.html">safety contract</a>, which you sign on Canvas this week. Your page will be public, so treat everything in it as public. Personal writing goes on Canvas, never in a repository (<a href="./../../assessment/#privacy-of-your-work">Privacy of your work</a>).</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><p>At the end of Studio B you complete the Week 1 exit ticket with 🔴 AI off: explain parts of <strong>your own page</strong> in plain English, and why an AI can give two different answers to the same question. It&#39;s scored for completion, not correctness.</p><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p>About 5 hours, including project time; details on the <a href="./homework.html">homework page</a>. Finish your page and add one small feature written entirely by hand (🔴 AI off), then upload it to Canvas · the first half of the AI Fluency course · the week 0 tasks (safety contract, self-assessment, GitHub Education) · a reflection on Canvas (🔴 AI off). Graded on effort and completion of the core tier (<a href="./../../assessment/rubrics.html#weekly-labs-and-homework">rubric</a>).</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>Gemini is down, blocked, or won&#39;t open its Canvas tool</td><td>Use a fallback from the <a href="./../../TOOLS.html">Tool Handout</a>: Claude with Artifacts (18+) has a live preview; with ChatGPT, run the code yourself (<a href="./lab.html#no-preview-run-it-yourself">No preview? Run it yourself</a>)</td></tr><tr><td>&quot;Not available for your account&quot; in Gemini</td><td>Switch from a school or work account to a personal Google account</td></tr><tr><td>You hit a usage limit</td><td>Switch to the next tool in the row and paste in your current code (<a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a>)</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Andrej Karpathy, <a href="https://karpathy.bearblog.dev/sequoia-ascent-2026/" target="_blank" rel="noreferrer">notes from his 2026 Sequoia talk</a> on vibe coding versus agentic engineering.</li><li>MDN, <a href="https://developer.mozilla.org/en-US/docs/Learn_web_development" target="_blank" rel="noreferrer">Learn web development</a>: the reference most web developers use.</li><li>More readings and free courses: the <a href="./../../resources/reading-list.html">Reading List</a>.</li></ul>',42)])])}const p=t(n,[["render",i]]);export{g as __pageData,p as default};
